src/interfaces/AggregatorV3Interface.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title AggregatorV3Interface (minimal)
/// @notice Chainlink's standard price-feed interface — only the two
/// functions `BondingCurve` needs (`decimals` read once at construction,
/// `latestRoundData` read live on every sell that could be whale-taxed).
/// Deliberately NOT the full interface — this codebase vendors only what
/// it calls.
interface AggregatorV3Interface {
    function decimals() external view returns (uint8);

    function latestRoundData()
        external
        view
        returns (uint80 roundId, int256 answer, uint256 startedAt, uint256 updatedAt, uint80 answeredInRound);
}

src/interfaces/IInfoFiCampaign.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title IInfoFiCampaign (minimal)
/// @notice The single call `BondingCurve` makes into the protocol-wide
/// `InfoFiCampaign` singleton, declared separately so the two contracts can
/// reference each other without a circular import.
interface IInfoFiCampaign {
    /// @notice Records the InfoFi pool a freshly-deployed curve has just
    /// transferred in. Called exactly once per token, from the curve's own
    /// constructor, AFTER the tokens have already been sent — the campaign
    /// verifies the balance actually arrived rather than trusting `amount`.
    /// @param token The launch token whose pool is being registered.
    /// @param amount Pool size in token base units. Immutable once set.
    function registerAllocation(address token, uint256 amount) external;
}

src/interfaces/IReferralVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/// @title IReferralVault (minimal)
/// @notice The two calls `BondingCurve` makes into the protocol-wide
/// `ReferralVault` singleton, declared separately so the two contracts can
/// reference each other without a circular import.
interface IReferralVault {
    /// @notice `wallet`'s permanent referrer, or the zero address if none.
    /// Read once, at construction, and cached as an immutable — a curve
    /// never re-checks this after deployment.
    function getReferrer(address wallet) external view returns (address);

    /// @notice Credits `referrer`'s pull-payment balance with `msg.value`.
    /// Called at fee-accrual time with that trade's referral cut.
    function creditReferral(address referrer) external payable;
}

